{
  "title": "Conversation stats",
  "body": "<div class="panel"><section><h2>Messages by role</h2><div class="total">Total: <strong id="total">0</strong></div><ul id="roles"></ul></section><section><h2>Five most recent tool calls</h2><ol id="calls"></ol></section><section><h2>Longest message</h2><div id="longest"></div></section></div>",
  "css": ".panel{font-family:system-ui,sans-serif;padding:12px;color:#222}h2{font-size:13px;text-transform:uppercase;letter-spacing:.05em;color:#666;margin:16px 0 6px}section:first-child h2{margin-top:0}ul,ol{margin:0;padding-left:20px}ul{list-style:none;padding:0}li{padding:3px 0}#roles li{display:flex;justify-content:space-between;border-bottom:1px solid #eee;max-width:240px}.total{margin-bottom:6px}.empty{color:#999;font-style:italic}.big{font-size:22px;font-weight:600}.sub{color:#666;font-size:13px}code{background:#f1f1f1;padding:1px 5px;border-radius:3px}",
  "scripts": [
    "const msgs = (ml.current && ml.current.messages) ? ml.current.messages : [];
const counts = { system: 0, user: 0, assistant: 0, tool: 0 };
for (const m of msgs) { counts[m.role] = (counts[m.role] ?? 0) + 1; }
root.querySelector('#total').textContent = String(msgs.length);
const rolesEl = root.querySelector('#roles');
rolesEl.replaceChildren();
for (const [role, n] of Object.entries(counts)) {
  const li = root.create('li');
  const a = root.create('span');
  a.textContent = role;
  const b = root.create('strong');
  b.textContent = String(n);
  li.append(a);
  li.append(b);
  rolesEl.append(li);
}
const calls = [];
for (const m of msgs) {
  for (const c of (m.tool_calls ?? [])) {
    calls.push(c?.function?.name ?? '(unnamed)');
  }
}
const recent = calls.slice(-5).reverse();
const callsEl = root.querySelector('#calls');
callsEl.replaceChildren();
if (recent.length === 0) {
  const li = root.create('li');
  li.textContent = 'No tool calls yet';
  li.classList.add('empty');
  callsEl.append(li);
} else {
  for (const name of recent) {
    const li = root.create('li');
    const code = root.create('code');
    code.textContent = name;
    li.append(code);
    callsEl.append(li);
  }
}
const longest = msgs.reduce((acc, m, i) => {
  const len = String(m.content ?? '').length;
  return len > acc.len ? { len, role: m.role, index: i + 1 } : acc;
}, { len: 0, role: null, index: 0 });
const lEl = root.querySelector('#longest');
lEl.replaceChildren();
const big = root.create('div');
big.classList.add('big');
big.textContent = longest.len + ' characters';
lEl.append(big);
const sub = root.create('div');
sub.classList.add('sub');
sub.textContent = longest.role ? ('message #' + longest.index + ' (' + longest.role + ')') : 'no messages yet';
lEl.append(sub);"
  ]
}
